/**
 * FileItem Component - Displays a single file
 * 
 * Responsibilities:
 * - Show file name, size, type
 * - Handle file click (download)
 * - Show file icon based on type
 * 
 * Import rules:
 * - Can import: hooks (if needed)
 * - Can import: other components
 * - Should NOT import: services, pages
 */

import React from 'react';

const FileItem = ({ file, onDownload, onDelete }) => {
  const formatSize = (bytes) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  return (
    <div className="file-item">
      <div className="file-icon">{/* Icon based on file.mime_type */}</div>
      <div className="file-info">
        <div className="file-name">{file.name}</div>
        <div className="file-meta">
          {formatSize(file.size_bytes)} • {file.mime_type}
        </div>
      </div>
      <div className="file-actions">
        <button onClick={() => onDownload(file.id)}>Download</button>
        <button onClick={() => onDelete(file.id)}>Delete</button>
      </div>
    </div>
  );
};

export default FileItem;
